insert into comments (id, item_id, author, body, upvotes, display_order) values
  ('ilovechipotle1301_c01', 'ilovechipotle1301', '@gregory_est95', 'The racism is LOUD', 0, 1),
  ('ilovechipotle1301_c02', 'ilovechipotle1301', '@ellisyolanda', 'I am old enough to remember when South Africa was ruled by a white upper class and they threw people like Nelson Mandela in jail.', 0, 2),
